import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillTonePipe } from "../../lib/pill-tone.pipe";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-224",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, PillTonePipe, CardComponent ],
    template: `
        <app-card heading="Feature 224" [disableTooltip]="true">
            <!-- disableTooltip here is the card's flag; pills carry their own -->
            <app-pill
                tone="caution"
                [tooltip]="false">Plain</app-pill>
            <app-pill
                [tone]="count > 3 ? 'positive' : isActive ? 'caution' : 'neutral'"
                [tooltip]="isActive && count > 1">{{ title }}</app-pill>
            <app-pill [tone]="statusVariant | pillTone" [tooltip]="true">Nested</app-pill>
            @if (disableTooltip) {
                <small>Own flag, unrelated to the pill input</small>
            }
        </app-card>
    `
})
export class Feature224Component {
    isActive = true;
    count = 0;
    disableTooltip = false;
    title = "Title 224";
<app-card heading="Feature 1" [disableTooltip]="true">
  <p class="hint">Set disableTooltip on a pill to hide its hint.</p>
  <app-pill [tooltip]="false">Plain</app-pill>
  <app-pill tone="positive" [tooltip]="isActive">Active</app-pill>
  <app-pill [tooltip]="!(count > 3)" tone="neutral">{{ title }}</app-pill>
  <app-pill [tone]="isActive ? 'positive' : 'caution'" [tooltip]="!isActive">Multi-line</app-pill>
  @if (isActive) {
    <app-pill-legacy label="Legacy" variant="info" [disableTooltip]="true" />
  }
  @if (disableTooltip) {
    <small>Own flag, unrelated to the pill input</small>
  }
</app-card>

